import React, { useEffect, useState } from 'react';
import { useOLAPStore } from '../store/olap-store';
import { olap } from '../api/olap-client';
import DimensionSelector from './DimensionSelector';
import FilterPanel from './FilterPanel';
import DataTable from './DataTable';
import ChartRenderer from './ChartRenderer';
import CrossAnalysisPanel from './CrossAnalysisPanel';
import DrillThroughModal from './DrillThroughModal';
import PivotTable from './PivotTable';
import SummaryCards from './SummaryCards';

const OLAPDashboard = () => {
  const selectedYear = useOLAPStore((state) => state.selectedYear);
  const selectedQuarter = useOLAPStore((state) => state.selectedQuarter);
  const selectedMonth = useOLAPStore((state) => state.selectedMonth);
  const selectedCube = useOLAPStore((state) => state.selectedCube);
  const viewMode = useOLAPStore((state) => state.viewMode);
  const filters = useOLAPStore((state) => state.filters);

  const setLoading = useOLAPStore((state) => state.setLoading);
  const setCuboidData = useOLAPStore((state) => state.setCuboidData);
  const cuboidData = useOLAPStore((state) => state.cuboidData);
  const loading = useOLAPStore((state) => state.loading);

  const [salesTotal, setSalesTotal] = useState(null);
  const [inventoryTotal, setInventoryTotal] = useState(null);
  const [crossAnalysisData, setCrossAnalysisData] = useState([]);
  const [drillThroughData, setDrillThroughData] = useState([]);
  const [drillThroughPagination, setDrillThroughPagination] = useState({});
  const [showDrillThrough, setShowDrillThrough] = useState(false);

  const setSelectedCube = useOLAPStore((state) => state.setSelectedCube);
  const setViewMode = useOLAPStore((state) => state.setViewMode);
  const setFilters = useOLAPStore((state) => state.setFilters);

  // Clear filters when cube changes
  useEffect(() => {
    if (selectedCube === 'sales') {
      // Sales cube: keep customerType, customerKey & productKey, clear storeKey
      if (filters.storeKey) {
        setFilters({ ...filters, storeKey: null });
      }
    } else if (selectedCube === 'inventory') {
      // Inventory cube: keep storeKey & productKey, clear customerType & customerKey
      if (filters.customerType || filters.customerKey) {
        setFilters({ ...filters, customerType: null, customerKey: null });
      }
    }
  }, [selectedCube]);

  // Load data when dimensions/filters change
  useEffect(() => {
    loadData();
    loadSummary();
  }, [selectedYear, selectedQuarter, selectedMonth, selectedCube, filters]);

  const filterDataByDimensions = (data) => {
    if (!data || data.length === 0) return data;

    if (data.length > 0) {
      console.log('🔍 First record sample:', data[0]);
      console.log('🔍 Columns:', Object.keys(data[0]));
    }

    let filtered = data;

    // Filter by quarter if selected (quarters: 1-3=Q1, 4-6=Q2, 7-9=Q3, 10-12=Q4)
    if (selectedQuarter) {
      const quarterMonths = {
        1: [1, 2, 3],
        2: [4, 5, 6],
        3: [7, 8, 9],
        4: [10, 11, 12],
      };
      const validMonths = quarterMonths[selectedQuarter] || [];
      const beforeQuarterFilter = filtered.length;
      filtered = filtered.filter((row) => validMonths.includes(row.month));
      console.log(`✅ Quarter filter (Q${selectedQuarter}): ${beforeQuarterFilter} → ${filtered.length}`);
    }

    // Filter by month if selected (AFTER quarter, to further refine)
    if (selectedMonth) {
      const beforeMonthFilter = filtered.length;
      filtered = filtered.filter((row) => row.month === selectedMonth);
      console.log(`✅ Month filter (${selectedMonth}): ${beforeMonthFilter} → ${filtered.length}`);
    }

    // Filter by customerType if selected (for Sales cube)
    if (filters.customerType) {
      const beforeCustFilter = filtered.length;
      filtered = filtered.filter((row) => row.customer_type === filters.customerType);
      console.log(`✅ Customer Type filter (${filters.customerType}): ${beforeCustFilter} → ${filtered.length}`);
      console.log('🔍 Unique customer_types:', [...new Set(data.map(r => r.customer_type))]);
    }

    // Filter by customerKey if selected (for Sales cube)
    if (filters.customerKey) {
      const beforeCustKeyFilter = filtered.length;
      filtered = filtered.filter((row) => row.customer_key === parseInt(filters.customerKey));
      console.log(`✅ Customer Key filter (${filters.customerKey}): ${beforeCustKeyFilter} → ${filtered.length}`);
    }

    // Filter by productKey if selected
    if (filters.productKey) {
      const beforeProdFilter = filtered.length;
      const prodKeyNum = parseInt(filters.productKey);
      
      // Debug: show data values
      if (filtered.length > 0) {
        console.log('🔍 Product filter debug:', {
          filterValue: filters.productKey,
          filterValueAsInt: prodKeyNum,
          firstRecordProductKey: filtered[0].product_key,
          firstRecordProductKeyType: typeof filtered[0].product_key,
          uniqueProductKeysInData: [...new Set(filtered.map(r => r.product_key))].slice(0, 5),
        });
      }
      
      filtered = filtered.filter((row) => row.product_key === prodKeyNum);
      console.log(`✅ Product filter (${filters.productKey} → ${prodKeyNum}): ${beforeProdFilter} → ${filtered.length}`);
    }

    // Filter by storeKey if selected (for Inventory cube)
    if (filters.storeKey) {
      const beforeStoreFilter = filtered.length;
      const storeKeyNum = parseInt(filters.storeKey);
      
      // Debug: show data values
      if (filtered.length > 0) {
        console.log('🔍 Store filter debug:', {
          filterValue: filters.storeKey,
          filterValueAsInt: storeKeyNum,
          firstRecordStoreKey: filtered[0].store_key,
          firstRecordStoreKeyType: typeof filtered[0].store_key,
          uniqueStoreKeysInData: [...new Set(filtered.map(r => r.store_key))].slice(0, 5),
        });
      }
      
      filtered = filtered.filter((row) => row.store_key === storeKeyNum);
      console.log(`✅ Store filter (${filters.storeKey} → ${storeKeyNum}): ${beforeStoreFilter} → ${filtered.length}`);
    }

    return filtered;
  };

  const loadData = async () => {
    setLoading(true);
    try {
      let data = [];

      if (selectedCube === 'sales') {
        // Choose endpoint based on filters
        if (filters.customerType) {
          // Need customer_type column → use endpoint that returns it
          data = await (await olap.getSalesMonthByCustType(selectedYear)).data;
        } else if (filters.productKey) {
          // Need product_key column → would need specific endpoint
          data = await (await olap.getSalesByMonth(selectedYear)).data;
        } else {
          // No filters → basic month breakdown
          data = await (await olap.getSalesByMonth(selectedYear)).data;
        }
      } else {
        // Inventory cube
        if (filters.storeKey) {
          data = await (await olap.getInventoryMonthProductStore(selectedYear, filters.storeKey)).data;
        } else if (filters.productKey) {
          // Would need product breakdown endpoint
          data = await (await olap.getInventoryByMonth(selectedYear)).data;
        } else {
          data = await (await olap.getInventoryByMonth(selectedYear)).data;
        }
      }

      console.log('🔍 DEBUG - Data before filter:', data.length, 'records');
      console.log('🔍 DEBUG - Selected filters:', { selectedYear, selectedQuarter, selectedMonth, filters });

      // Filter data based on all selected dimensions and filters
      data = filterDataByDimensions(data);
      
      console.log('🔍 DEBUG - Data after filter:', data.length, 'records');
      
      setCuboidData(data);
    } catch (error) {
      console.error('❌ Error loading data:', error);
    }
  };

  const loadSummary = async () => {
    try {
      const sales = await (await olap.getSalesTotal()).data;
      const inventory = await (await olap.getInventoryTotal()).data;
      setSalesTotal(sales);
      setInventoryTotal(inventory);
    } catch (error) {
      console.error('Error loading summary:', error);
    }
  };

  const handleDrillAcross = async () => {
    setLoading(true);
    try {
      const data = await (await olap.getCrossAnalysisSalesVsInventoryByProduct()).data;
      setCrossAnalysisData(data);
      setViewMode('crossanalysis');
    } catch (error) {
      console.error('Error loading cross analysis:', error);
    } finally {
      setLoading(false);
    }
  };

  const handleDrillThrough = async (record) => {
    setLoading(true);
    try {
      const data = await olap.drillThroughSales(selectedYear, undefined, filters.customerType);
      setDrillThroughData(data.data);
      setDrillThroughPagination(data.pagination);
      setShowDrillThrough(true);
    } catch (error) {
      console.error('Error drill through:', error);
    } finally {
      setLoading(false);
    }
  };

  return (
    <div style={{
      fontFamily: "'Segoe UI', Tahoma, Geneva, Verdana, sans-serif",
      backgroundColor: '#f0f2f5',
      minHeight: '100vh',
      padding: '20px',
    }}>
      {/* Header */}
      <header style={{
        backgroundColor: 'white',
        padding: '30px',
        borderRadius: '12px',
        boxShadow: '0 4px 6px rgba(0, 0, 0, 0.1)',
        marginBottom: '30px',
        textAlign: 'center',
      }}>
        <h1 style={{ color: '#667eea', marginBottom: '5px' }}>📊 OLAP Dashboard v2.0</h1>
        <p style={{ color: '#999', margin: 0 }}>56 Cuboid Analysis with 7 OLAP Operations</p>
      </header>

      <div style={{ maxWidth: '1400px', margin: '0 auto' }}>
        {/* Cube & View Mode Selector */}
        <div style={{
          display: 'grid',
          gridTemplateColumns: 'repeat(auto-fit, minmax(200px, 1fr))',
          gap: '15px',
          marginBottom: '20px',
          backgroundColor: 'white',
          padding: '15px',
          borderRadius: '12px',
          boxShadow: '0 4px 6px rgba(0, 0, 0, 0.1)',
        }}>
          <div>
            <label style={{ fontWeight: '600', color: '#667eea', display: 'block', marginBottom: '5px' }}>Khối (Cube)</label>
            <select
              value={selectedCube}
              onChange={(e) => {
                setSelectedCube(e.target.value);
                setViewMode('drilldown');
              }}
              style={{ width: '100%', padding: '8px', border: '2px solid #ddd', borderRadius: '4px' }}
            >
              <option value="sales">📈 Sales (Doanh Thu)</option>
              <option value="inventory">📦 Inventory (Tồn Kho)</option>
            </select>
          </div>

          <div>
            <label style={{ fontWeight: '600', color: '#667eea', display: 'block', marginBottom: '5px' }}>Chế Độ Xem</label>
            <select
              value={viewMode}
              onChange={(e) => setViewMode(e.target.value)}
              style={{ width: '100%', padding: '8px', border: '2px solid #ddd', borderRadius: '4px' }}
            >
              <option value="drilldown">🔍 Drill-Down</option>
              <option value="pivot">🔀 Pivot</option>
              <option value="crossanalysis">↔️ Drill Across</option>
            </select>
          </div>

          <div style={{ display: 'flex', alignItems: 'flex-end', gap: '10px' }}>
            <button
              onClick={handleDrillAcross}
              style={{
                flex: 1,
                padding: '8px',
                backgroundColor: '#764ba2',
                color: 'white',
                border: 'none',
                borderRadius: '4px',
                fontWeight: '600',
                cursor: 'pointer',
              }}
            >
              ↔️ Sales vs Inventory
            </button>
          </div>
        </div>

        {/* Summary Cards */}
        <SummaryCards salesTotal={salesTotal} inventoryTotal={inventoryTotal} selectedCube={selectedCube} />

        {/* Dimension Selector (Drill-Down) */}
        <DimensionSelector onDimensionChange={loadData} />

        {/* Filter Panel (Slice/Dice) */}
        <FilterPanel onApply={loadData} selectedCube={selectedCube} />

        {/* Main Content Area */}
        {loading && <div style={{ textAlign: 'center', padding: '40px', color: '#999' }}>⏳ Đang tải dữ liệu...</div>}

        {!loading && viewMode === 'drilldown' && (
          <div style={{
            display: 'grid',
            gridTemplateColumns: 'repeat(auto-fit, minmax(500px, 1fr))',
            gap: '25px',
            marginBottom: '30px',
          }}>
            {/* Chart */}
            <div style={{ backgroundColor: 'white', padding: '20px', borderRadius: '12px', boxShadow: '0 4px 6px rgba(0, 0, 0, 0.1)' }}>
              <h3 style={{ color: '#667eea', marginBottom: '15px' }}>📊 Biểu Đồ</h3>
              <ChartRenderer
                data={cuboidData}
                type="bar"
                xKey={selectedCube === 'sales' ? 'customer_type' : 'product_key'}
                yKey={selectedCube === 'sales' ? 'sum_amount' : 'total_quantity_on_hand'}
              />
            </div>

            {/* Table */}
            <div style={{ backgroundColor: 'white', padding: '20px', borderRadius: '12px', boxShadow: '0 4px 6px rgba(0, 0, 0, 0.1)' }}>
              <h3 style={{ color: '#667eea', marginBottom: '15px' }}>📋 Bảng Dữ Liệu</h3>
              <DataTable data={cuboidData} onDrillThrough={handleDrillThrough} />
            </div>
          </div>
        )}

        {!loading && viewMode === 'crossanalysis' && (
          <CrossAnalysisPanel data={crossAnalysisData} title="Sales vs Inventory by Product" />
        )}

        {!loading && viewMode === 'pivot' && (
          <div style={{ backgroundColor: 'white', padding: '20px', borderRadius: '12px', boxShadow: '0 4px 6px rgba(0, 0, 0, 0.1)' }}>
            <h3 style={{ color: '#667eea', marginBottom: '15px' }}>🔀 Pivot Table</h3>
            <PivotTable
              data={cuboidData}
              rowDimension={selectedCube === 'sales' ? 'customer_type' : 'product_key'}
              colDimension="month"
              valueDimension={selectedCube === 'sales' ? 'sum_amount' : 'total_quantity_on_hand'}
            />
          </div>
        )}
      </div>

      {/* Drill Through Modal */}
      <DrillThroughModal
        isOpen={showDrillThrough}
        onClose={() => setShowDrillThrough(false)}
        data={drillThroughData}
        pagination={drillThroughPagination}
        title="Drill Through - Raw Transaction Data"
      />

      {/* Footer */}
      <footer style={{ textAlign: 'center', color: '#999', marginTop: '40px', fontSize: '0.9em' }}>
        © 2026 PTIT - Data Warehouse & Data Mining | React + FastAPI + 56 Cuboid OLAP
      </footer>
    </div>
  );
};

export default OLAPDashboard;
